CREATE   PROCEDURE [synapse_ce].[usp_Update_apuk_directdebitdetail]
AS
BEGIN
	UPDATE tgt SET 
		tgt.[apuk_accountnumber] = stg.[apuk_accountnumber],
		tgt.[apuk_authorisationdate] = stg.[apuk_authorisationdate],
		tgt.[apuk_bankaccountid] = stg.[apuk_bankaccountid],
		tgt.[apuk_bankaddresscity] = stg.[apuk_bankaddresscity],
		tgt.[apuk_bankaddresscountryid] = stg.[apuk_bankaddresscountryid],
		tgt.[apuk_bankaddresscountryid_entitytype] = stg.[apuk_bankaddresscountryid_entitytype],
		tgt.[apuk_bankaddresscountryidname] = stg.[apuk_bankaddresscountryidname],
		tgt.[apuk_bankaddresscounty] = stg.[apuk_bankaddresscounty],
		tgt.[apuk_bankaddressline1] = stg.[apuk_bankaddressline1],
		tgt.[apuk_bankaddressline2] = stg.[apuk_bankaddressline2],
		tgt.[apuk_bankaddressline3] = stg.[apuk_bankaddressline3],
		tgt.[apuk_bankaddresspostcode] = stg.[apuk_bankaddresspostcode],
		tgt.[apuk_bankaddressstateorprovince] = stg.[apuk_bankaddressstateorprovince],
		tgt.[apuk_bankname] = stg.[apuk_bankname],
		tgt.[apuk_commencementdate] = stg.[apuk_commencementdate],
		tgt.[apuk_currencyid] = stg.[apuk_currencyid],
		tgt.[apuk_currencyid_entitytype] = stg.[apuk_currencyid_entitytype],
		tgt.[apuk_currencyidname] = stg.[apuk_currencyidname],
		tgt.[apuk_customerid] = stg.[apuk_customerid],
		tgt.[apuk_customerid_entitytype] = stg.[apuk_customerid_entitytype],
		tgt.[apuk_customeridname] = stg.[apuk_customeridname],
		tgt.[apuk_customeridtype] = stg.[apuk_customeridtype],
		tgt.[apuk_customeridyominame] = stg.[apuk_customeridyominame],
		tgt.[apuk_directdebitdetailid] = stg.[apuk_directdebitdetailid],
		tgt.[apuk_iban] = stg.[apuk_iban],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_paymentcycle] = stg.[apuk_paymentcycle],
		tgt.[apuk_paymenttext] = stg.[apuk_paymenttext],
		tgt.[apuk_ricscompany] = stg.[apuk_ricscompany],
		tgt.[apuk_ricscompany_entitytype] = stg.[apuk_ricscompany_entitytype],
		tgt.[apuk_ricscompanyname] = stg.[apuk_ricscompanyname],
		tgt.[apuk_sortcode] = stg.[apuk_sortcode],
		tgt.[apuk_transferredtofinops] = stg.[apuk_transferredtofinops],
		tgt.[createdby] = stg.[createdby],
		tgt.[createdby_entitytype] = stg.[createdby_entitytype],
		tgt.[createdbyname] = stg.[createdbyname],
		tgt.[createdbyyominame] = stg.[createdbyyominame],
		tgt.[createdon] = stg.[createdon],
		tgt.[createdonbehalfby] = stg.[createdonbehalfby],
		tgt.[createdonbehalfby_entitytype] = stg.[createdonbehalfby_entitytype],
		tgt.[createdonbehalfbyname] = stg.[createdonbehalfbyname],
		tgt.[createdonbehalfbyyominame] = stg.[createdonbehalfbyyominame],
		tgt.[importsequencenumber] = stg.[importsequencenumber],
		tgt.[modifiedby] = stg.[modifiedby],
		tgt.[modifiedby_entitytype] = stg.[modifiedby_entitytype],
		tgt.[modifiedbyname] = stg.[modifiedbyname],
		tgt.[modifiedbyyominame] = stg.[modifiedbyyominame],
		tgt.[modifiedon] = stg.[modifiedon],
		tgt.[modifiedonbehalfby] = stg.[modifiedonbehalfby],
		tgt.[modifiedonbehalfby_entitytype] = stg.[modifiedonbehalfby_entitytype],
		tgt.[modifiedonbehalfbyname] = stg.[modifiedonbehalfbyname],
		tgt.[modifiedonbehalfbyyominame] = stg.[modifiedonbehalfbyyominame],
		tgt.[organizationid] = stg.[organizationid],
		tgt.[organizationid_entitytype] = stg.[organizationid_entitytype],
		tgt.[organizationidname] = stg.[organizationidname],
		tgt.[overriddencreatedon] = stg.[overriddencreatedon],
		tgt.[SinkCreatedOn] = stg.[SinkCreatedOn],
		tgt.[SinkModifiedOn] = stg.[SinkModifiedOn],
		tgt.[statecode] = stg.[statecode],
		tgt.[statuscode] = stg.[statuscode],
		tgt.[timezoneruleversionnumber] = stg.[timezoneruleversionnumber],
		tgt.[utcconversiontimezonecode] = stg.[utcconversiontimezonecode],
		tgt.[versionnumber] = stg.[versionnumber]
	 FROM [synapse_ce].[apuk_directdebitdetail] tgt
		INNER JOIN [staging_ce].[apuk_directdebitdetail] stg
			ON tgt.[id] = stg.[id]
END
